// Counts describe the reviewed local action, not every player in the camera frame.
// References resolve to manually reviewed records; no pixel tracking is implied.
export const LOCAL_PLAYERS={
 'pitchside-duel':{attackers:1,defenders:1},
 'pitchside-outlet':{attackers:2,defenders:1},
 'pitchside-control':{attackers:1,defenders:1},
 'pitchside-stance':{attackers:1,defenders:1},
 'pitchside-balance':{attackers:1,defenders:1},
 'pitchside-teammates':{attackers:2,defenders:null},
 'pitchside-blue-start':{attackers:2,defenders:null}
};
export const FILM_SCENES=[
 {start:0,end:8,id:'00-duel'}, {start:8,end:16,id:'01-pass'},
 {start:16,end:24,id:'02-turn'}, {start:24,end:32,id:'03-defend'},
 {start:32,end:40,id:'04-line'}, {start:40,end:48,id:'05-keeper'},
 {start:48,end:52,id:'06-talk'}, {start:52,end:60,id:'07-blue'}
];
export function sceneStudy(time,enabled){
 const scene=FILM_SCENES.findLast(s=>s.start<=Math.max(0,Math.min(60,time)))||FILM_SCENES[0];
 return {scene,complete:!!enabled&&time>=scene.end-.05,replayAt:scene.start,nextAt:scene.end>=60?0:scene.end};
}
export function scenePlayback(previous,next,study){
 const scene=FILM_SCENES.findLast(s=>s.start<=Math.max(0,Math.min(60,previous)))||FILM_SCENES[0];
 return study&&next>=scene.end?{time:scene.end-1/24,stop:true}:{time:next,stop:false};
}
