export function filmMath({time=0,language='en',evidence=[]}={}){
 const c=text[language]||text.en,scene=FILM_SCENES.findLast(s=>s.start<=Math.max(0,Math.min(60,time)))||FILM_SCENES[0];
 const records=evidence.filter(e=>e.shot_id===scene.id&&e.second<=time),countRecord=records.findLast(e=>e.local_players),players=countRecord?.local_players;
 const reception=records.find(e=>['pitchside-reception','pitchside-blue-receive'].includes(e.id)),caught=records.find(e=>e.id==='pitchside-catch');
 let kind='waiting',title=c.waiting,summary=c.waitBody,value='—',equation=c.noFormula,ids=[],edge=null;
 if(players){ids=[countRecord.id];if(players.defenders!==null){edge=players.attackers-players.defenders;kind=edge>0?'overload':'balance';value=`${players.attackers} v ${players.defenders}`;equation=`${c.edge}: ${players.attackers} − ${players.defenders} = ${edge>0?'+':''}${edge}.`;title=c[kind];summary=c[kind+'Body'];}else{kind=scene.id==='06-talk'?'gesture':'pair';value='2';title=c[kind];summary=c[kind+'Body'];equation=c.pairFormula;}}
 if(reception){kind='reception';title=c.received;summary=c.receiveBody;ids.push(reception.id);if(!players||players.defenders===null)value='1';equation+=(players?'\n':'')+c.passFormula;}
 if(caught){kind='catch';title=c.catch;summary=c.catchBody;value='1';equation=c.catchFormula;ids=[caught.id];}
 return {kind,title,summary,value,equation,scope:c.scope,scene,records,players:players||null,edge,receptions:reception?1:null,catches:caught?1:null,evidence_ids:[...new Set(ids)],labels:c};
}
